const iconUrl = {};
function buildIcons(){
  const c = document.createElement("canvas"); c.width = 10; c.height = 10; const g = c.getContext("2d");
  for (const k in ICONS){
    g.clearRect(0,0,10,10);
    const rows = ICONS[k];
    g.fillStyle = "rgba(0,0,0,.35)";
    rows.forEach((r,y)=>[...r].forEach((ch,x)=>{ if (ch!=="."&&ch!==" ") g.fillRect(x+2,y+2,1,1); }));
    rows.forEach((r,y)=>[...r].forEach((ch,x)=>{ if (ch!=="."&&ch!==" "){ g.fillStyle = PAL[ch]||"#f0f"; g.fillRect(x+1,y+1,1,1); } }));
    iconUrl[k] = c.toDataURL();
  }
}
const iconOf = it => iconUrl[iconFor(it)];
