function shade(hex, amt){
  const n = parseInt(hex.slice(1,7),16); const r = n>>16, gg = (n>>8)&255, b = n&255;
  const f = v => clamp(Math.round(amt<0 ? v*(1+amt) : v+(255-v)*amt),0,255);
  return "#"+[f(r),f(gg),f(b)].map(v=>v.toString(16).padStart(2,"0")).join("");
}
function toast(msg, kind="", secs=3.5){
  const el = document.createElement("div"); el.className = "toast "+kind; el.textContent = msg;
  const box = $("toasts"); box.append(el); while (box.children.length > 3) box.firstChild.remove();
  setTimeout(()=>el.remove(), secs*1000);
}
let bannerT = null;
function banner(big, small, red, secs=3){
  const b = $("banner"); $("bannerBig").textContent = big; $("bannerSmall").textContent = small||""; $("bannerSmall").hidden = !small;
  b.classList.toggle("red", !!red); b.style.opacity = 1;
  clearTimeout(bannerT); bannerT = setTimeout(()=>{ b.style.opacity = 0; }, secs*1000);
}
function drawHeart(c, full){
  const rows = [".kk.kk..","krrkrrk.","krwrrrk.","krrrrrk.",".krrrk..","..krk...","...k...."];
  c.clearRect(0,0,9,9);
  rows.forEach((r,y)=>[...r].forEach((ch,x)=>{ if (ch===".") return; c.fillStyle = full ? PAL[ch] : (ch==="k"?PAL.k:PAL.d); c.fillRect(x,y+1,1,1); }));
}
function drawLock(c){
  const rows = ["..kkk...",".k...k..",".k...k..","kkkkkkk.","kyyyyyk.","kyykyyk.","kyyyyyk.","kkkkkkk."];
  c.clearRect(0,0,9,9); rows.forEach((r,y)=>[...r].forEach((ch,x)=>{ if (ch===".") return; c.fillStyle = PAL[ch]; c.fillRect(x,y,1,1); }));
}
function wrap(text, max){
  const words = text.split(/\s+/), lines = []; let cur = "";
  for (const w of words){ if ((cur+" "+w).trim().length > max){ if (cur) lines.push(cur); cur = w; } else cur = (cur+" "+w).trim(); }
  if (cur) lines.push(cur); if (lines.length > 3){ lines.length = 3; lines[2] = lines[2].slice(0,max-1)+"…"; } return lines;
}
const opWord = v => v>=60?"Loves you":v>=30?"Likes you":v>=10?"Warming up":v>-10?"Neutral":v>-30?"Wary":v>-60?"Dislikes you":"Hates you";
