function slotsOf(inv){
  const order = [], counts = {};
  for (const it of inv){ if (!(it in counts)){ counts[it] = 0; order.push(it); } counts[it]++; }
  const out = [];
  for (const it of order){ let c = counts[it]; if (STACKS.has(it)){ while (c>0){ const k = Math.min(STACK_MAX, c); out.push({item:it, count:k}); c -= k; } } else for (let i=0;i<c;i++) out.push({item:it, count:1}); }
  return out;
}
